WHY={'Compute':'Run application code on virtual machines, containers or platform services.','Networking':'Connect, isolate, secure and distribute traffic between workloads, users and on-premises.','Storage':'Store blobs, files, messages, tables and disks durably with the redundancy you choose.','Identity':'Control who can sign in and what they can access across Azure and applications.','Security':'Protect workloads, secrets and data and reduce the attack surface.','Monitoring':'Collect, query and alert on metrics and logs so problems are found early.','Backup & DR':'Recover data and workloads after deletion, corruption or outage within your RPO and RTO.','Governance':'Organize resources and enforce standards, access and compliance at scale.','Cost':'Understand, control and reduce Azure spend.','IaC':'Define infrastructure as code so it is repeatable and reviewable.'}
MON={'Compute':'Enable boot diagnostics and the Azure Monitor agent; alert on CPU, memory and disk.','Networking':'Use Network Watcher, NSG flow logs and diagnostic settings; alert on health and throughput.','Storage':'Use storage metrics and diagnostic logs; alert on availability, latency and throttling.','Identity':'Review sign-in and audit logs; alert on risky sign-ins and role changes.','Security':'Send logs to Log Analytics; review Defender for Cloud alerts and secure score.','Monitoring':'Monitor ingestion volume and alert rule health.','Backup & DR':'Use Backup jobs, Site Recovery health and backup alerts.','Governance':'Review Policy compliance and the Activity log.','Cost':'Use budgets, anomaly alerts and Cost analysis views.','IaC':'Run drift detection in pipelines.'}
BKP={'Compute':'Protect VMs with Azure Backup; use Site Recovery for DR; keep configuration in code.','Networking':'Keep configuration as code or exported templates; there is no data to back up.','Storage':'Enable soft delete, versioning and point-in-time restore; consider Azure Backup for blobs and files.','Identity':'Document break-glass access and export configuration; protect with PIM.','Security':'Enable soft delete and purge protection; back up keys and certificates where supported.','Monitoring':'Export queries and workbooks as code; set retention.','Backup & DR':'Protect the vault with soft delete, immutability and multi-user authorization.','Governance':'Keep policy and role definitions in source control.','Cost':'Keep saved views and exports.','IaC':'Back up the state storage account.'}
MIS={'Compute':'Public management ports left open|Undersizing or oversizing without data|No backup or monitoring','Networking':'Overlapping address spaces|Allow-any NSG rules|Forgetting DNS and routing when adding peering or endpoints','Storage':'Anonymous access left on|Wrong redundancy for the RPO|Sharing account keys instead of using Entra ID','Identity':'Assigning roles to individuals|No break-glass account|Long-lived secrets','Security':'Secrets in code|Broad access policies|No logging on security resources','Monitoring':'Alerts without owners|Collecting every log category|No action group testing','Backup & DR':'Never testing a restore|Vault in the wrong region|Assuming backup equals DR','Governance':'Policy set to Deny without Audit first|Assignments at the wrong scope|Locks that block operations','Cost':'Buying commitments before right-sizing|No tags|Leaving idle resources running','IaC':'State in source control|Shared local state|No plan review'}
NOSOP={'Management groups':'Containers above subscriptions that let you apply Policy and RBAC across many subscriptions with inheritance.','Terraform (code, not a portal service)':'An infrastructure-as-code tool used with the AzureRM provider to deploy and manage Azure resources from configuration files.'}
_R=[l.split('|') for l in CAT.split('\n')]
svc='';_pt={p['n']:p for p in parts}
def _ul(a):return '<ul>'+''.join(f'<li>{E(x)}</li>' for x in a)+'</ul>'
for i,(n,c,pt,*r) in enumerate(_R):
    pt=int(pt);sid=r[0] if r else None;sp=sopid.get(sid) if sid else None
    rows=rows.replace(f'<td>{n}</td>',f'<td><a href="#s-{i}">{n}</a></td>',1)
    rec=(REC.get(sid) or [''])[0] if sid else ''
    h=f'<section class="view" id="v-s-{i}" data-svc="{E(n)}"><h1>{E(n)}</h1><p class="meta">{c} · <a href="#p{pt:02d}">Part {pt}: {E(_pt[pt]["short"])}</a></p>'
    h+=f'<h2>What is it?</h2><p>{E(sp["p"] if sp else NOSOP.get(n,"See the concept notes."))}</p><h2>Why and when to use it</h2><p>{E(WHY[c])}'+(f' Recommended starting point: {E(rec)}.' if rec else '')+'</p>'
    if sp:
        h+=f'<h2>Prerequisites</h2>{_ul(sp.get("pre",[]))}'
        if sp.get('arch'):h+=f'<h2>Architecture</h2><pre class="mermaid">{E(sp["arch"])}</pre>'
        h+=f'<h2>Portal location</h2><div class="crumb">'+''.join(f'<span>{x}</span>' for x in ['Azure Portal']+sp['nav'])+'</div>'
        h+=f'<h2>Creation and configuration</h2><p>{LV[sp["l"]]} · <a href="#sop-{sid}">Open the SOP: {E(sp["t"])}</a></p>'+(_ul(REC[sid]) if sid in REC else '')
    else:h+='<h2>Creation and configuration</h2><p>Covered in the concept notes and the Terraform Guide.</p>'
    h+=f'<h2>Security</h2>{_ul(sp.get("sec",["Apply least privilege and private access."]) if sp else ["Apply least privilege and private access."])}<h2>Monitoring</h2><p>{E(MON[c])}</p><h2>Backup and recovery</h2><p>{E(BKP[c])}</p>'
    if sp:h+='<h2>Troubleshooting</h2><div class="tw"><table><tr><th>Symptom</th><th>Check and fix</th></tr>'+''.join('<tr><td>%s</td><td>%s</td></tr>'%tuple(x.split(' => ')) for x in sp['ts'])+'</table></div>'
    h+=f'<h2>Best practices</h2>{_ul(BP[c].split("|") if c in BP else BP["Governance"].split("|"))}<h2>Common mistakes</h2>{_ul(MIS[c].split("|"))}<h2>Interview questions</h2>'
    for q,a in (XQ.get(pt) and [(XQ[pt][0],XQ[pt][1]),(XQ[pt][2],XQ[pt][3]),(XQ[pt][4],XQ[pt][5])] or [])+([IQ[pt]] if pt in IQ else []):h+=f'<details class="qa-item"><summary>{E(q)}</summary><div class="qa-answer"><p>{E(a)}</p></div></details>'
    h+='<h2>Official Microsoft documentation</h2><p>'+(' · '.join(f'<a href="{u}" target="_blank" rel="noopener">Microsoft Learn: {u.split("/")[-1]}</a>' for u in sp['d']) if sp else '<a href="https://learn.microsoft.com/en-us/azure/azure-portal/" target="_blank" rel="noopener">Azure portal documentation</a>')+'</p>'
    pv=f'<a href="#s-{i-1}">← {E(_R[i-1][0])}</a>' if i else '<span></span>';nx=f'<a href="#s-{i+1}" style="text-align:right">{E(_R[i+1][0])} →</a>' if i+1<len(_R) else ''
    svc+=h+f'<div class="pager">{pv}{nx}</div></section>'
sopchips=''.join(f'<h2 class="dom" id="dom-{_slug(c)}">{c} <small>({len(_g[c])} SOPs)</small></h2><div class="grid">'+''.join(f'<a class="card" href="#sop-{s["id"]}"><b>{E(s["t"])}</b><span>{E(s["p"])}</span></a>' for s in _g[c])+'</div>' for c in ORD)
soptree=''.join(f'<details class="tr" data-dom="{c}"><summary>{c} ({len(_g[c])})</summary>'+''.join(f'<a href="#sop-{s["id"]}">{E(s["t"])}</a>' for s in _g[c])+'</details>' for c in ORD)
AR=[('Azure hierarchy','Policy and RBAC set high in the tree are inherited downward.','flowchart TD\n T[Tenant] --> MG[Management group] --> S[Subscription] --> RG[Resource group] --> R[Resources]','#p02'),
('Hub-and-spoke network','A hub holds shared inspection and connectivity; spokes hold workloads and reach PaaS privately.','flowchart TD\n ON[On-premises] --> GW[VPN or ExpressRoute gateway] --> FW[Azure Firewall]\n BAS[Bastion] --> SP1\n FW --> SP1[Spoke VNet 1: subnets, VMs, NICs]\n FW --> SP2[Spoke VNet 2]\n SP1 --> PE[Private endpoint] --> PAAS[Storage or Key Vault]','#p05'),
('Identity','Sign-in, conditional controls, then authorization against Azure resources.','flowchart TD\n U[User] --> EID[Microsoft Entra ID] --> AUTH[Authentication and MFA] --> CA[Conditional Access] --> RBAC[Azure RBAC] --> RES[Azure resource]','#p04'),
('Monitoring','Resources emit telemetry that is stored, queried, alerted on and acted upon.','flowchart TD\n R[Resource] --> DS[Diagnostic settings] --> LAW[Log Analytics workspace] --> AM[Azure Monitor] --> AL[Alert rule] --> AG[Action group]','#p09'),
('Backup','Policy-driven recovery points held in a vault.','flowchart TD\n VM[VM] --> RSV[Recovery Services vault] --> POL[Backup policy] --> RP[Recovery point] --> RST[Restore]','#p10'),
('Disaster recovery','Replication to another region with a controlled failover.','flowchart TD\n P[Primary region VM] --> ASR[Site Recovery replication] --> T[DR region VM]\n T --> FO[Failover] --> FB[Re-protect and failback]','#p10'),
('Defense in depth','Layered controls from identity to data.','flowchart TD\n ID[Identity and access] --> PER[Perimeter: DDoS and Front Door WAF] --> NET[Network: NSG and Firewall] --> CMP[Compute: JIT and Defender] --> APP[Application: Key Vault and managed identity] --> DATA[Data: encryption and backup]','#p08'),
('Governance','Standards are applied by scope; compliance is reported back.','flowchart TD\n MG[Management group] --> POL[Azure Policy] --> COMP[Compliance]\n MG --> RB[RBAC]\n SUB[Subscription] --> LT[Locks and tags]','#p03'),
('Compute service selection','Choose by how much control you need.','flowchart TD\n W[Workload] --> Q1{"Need full OS control?"}\n Q1 -->|Yes| VM[Virtual machines or scale sets]\n Q1 -->|No| Q2{"Containers?"}\n Q2 -->|Yes| AKS[AKS or Container Instances]\n Q2 -->|No| Q3{"Event driven?"}\n Q3 -->|Yes| FN[Functions]\n Q3 -->|No| APP[App Service]','#p07'),
('Azure landing zone','How the previous areas fit into an enterprise design.','flowchart TD\n MG[Management groups] --> SUB[Subscriptions] --> ID[Identity] --> NET[Networking] --> SEC[Security] --> GOV[Governance] --> MON[Monitoring] --> COST[Cost management] --> WL[Workloads]','#p13')]
arch='<h1>Architecture</h1>'+''.join(f'<h2>{t}</h2><p>{d} <a href="{l}">Concept notes</a></p><pre class="mermaid">{E(m)}</pre>' for t,d,m,l in AR)
